def solution(hand, groupSize):
    if len(hand) % groupSize != 0:
        return False
    count = {}
    for card in hand:
        count[card] = count.get(card, 0) + 1
    sorted_keys = sorted(count.keys())
    for card in sorted_keys:
        if count[card] > 0:
            needed = count[card]
            for i in range(groupSize):
                if count.get(card + i, 0) < needed:
                    return False
                count[card + i] -= needed
    return True
